	    n = (*mb_ptr2char)(buf);
	}
#endif
#ifdef UNIX
	if (n == intr_char)
	    n = ESC;
#endif
	break;
    }
    vim_free(buf);
    mapped_ctrl_c = save_mapped_ctrl_c;
    return n;
}`

