	    vim_snprintf((char *)numbuf, NUMBUFLEN, "%ld",
						    (long)val->vval.v_number);
	    ga_concat(gap, numbuf);
	    break;
	case VAR_STRING:
	    res = val->vval.v_string;
	    write_string(gap, res);
	    break;
	case VAR_FUNC:
	case VAR_JOB:
	case VAR_CHANNEL:
	    EMSG(_(e_invarg));
	    return FAIL;
