	else
	    putc(*p, fd);
	--remaining;
	if (remaining < 3)
	{
	    putc('\n', fd);
	    putc('|', fd);
	    putc('<', fd);
	    remaining = LSIZE - 20;
	}
    }
    putc('"', fd);
    return remaining - 2;
