    varnumber_T		*nptr,	    
    uvarnumber_T	*unptr,	    
    int			maxlen)     
{
    char_u	    *ptr = start;
    int		    pre = 0;		
    int		    negative = FALSE;
    uvarnumber_T    un = 0;
    int		    n;
    if (ptr[0] == '-')
    {
	negative = TRUE;
	++ptr;
    }
    if (ptr[0] == '0' && ptr[1] != '8' && ptr[1] != '9'
					       && (maxlen == 0 || maxlen > 1))
    {
	pre = ptr[1];
	if ((what & STR2NR_HEX)
		&& (pre == 'X' || pre == 'x') && vim_isxdigit(ptr[2])
		&& (maxlen == 0 || maxlen > 2))
	    ptr += 2;
	else if ((what & STR2NR_BIN)
		&& (pre == 'B' || pre == 'b') && vim_isbdigit(ptr[2])
		&& (maxlen == 0 || maxlen > 2))
	    ptr += 2;
	else
	{
	    pre = 0;
	    if (what & STR2NR_OCT)
	    {
		for (n = 1; VIM_ISDIGIT(ptr[n]); ++n)
		{
		    if (ptr[n] > '7')
		    {
			pre = 0;	
			break;
		    }
		    if (ptr[n] >= '0')
			pre = '0';	
		    if (n == maxlen)
			break;
		}
	    }
	}
    }
    n = 1;
    if (pre == 'B' || pre == 'b' || what == STR2NR_BIN + STR2NR_FORCE)
    {
	if (pre != 0)
	    n += 2;	    
	while ('0' <= *ptr && *ptr <= '1')
	{
	    if (un < UVARNUM_MAX / 2)
		un = 2 * un + (unsigned long)(*ptr - '0');
	    else
		un = UVARNUM_MAX;
	    ++ptr;
	    if (n++ == maxlen)
		break;
	}
    }
    else if (pre == '0' || what == STR2NR_OCT + STR2NR_FORCE)
    {
	while ('0' <= *ptr && *ptr <= '7')
	{
	    if (un < UVARNUM_MAX / 8)
		un = 8 * un + (uvarnumber_T)(*ptr - '0');
	    else
		un = UVARNUM_MAX;
	    ++ptr;
	    if (n++ == maxlen)
		break;
	}
    }
    else if (pre != 0 || what == STR2NR_HEX + STR2NR_FORCE)
    {
	if (pre != 0)
	    n += 2;	    
	while (vim_isxdigit(*ptr))
	{
	    if (un < UVARNUM_MAX / 16)
		un = 16 * un + (uvarnumber_T)hex2nr(*ptr);
	    else
		un = UVARNUM_MAX;
	    ++ptr;
	    if (n++ == maxlen)
		break;
	}
    }
    else
    {
	while (VIM_ISDIGIT(*ptr))
	{
	    if (un < UVARNUM_MAX / 10)
		un = 10 * un + (uvarnumber_T)(*ptr - '0');
	    else
		un = UVARNUM_MAX;
	    ++ptr;
	    if (n++ == maxlen)
		break;
	}
    }
    if (prep != NULL)
	*prep = pre;
    if (len != NULL)
	*len = (int)(ptr - start);
    if (nptr != NULL)
    {
	if (negative)   
	{
	    if (un > VARNUM_MAX)
		*nptr = VARNUM_MIN;
	    else
		*nptr = -(varnumber_T)un;
	}
	else
	{
	    if (un > VARNUM_MAX)
		un = VARNUM_MAX;
	    *nptr = (varnumber_T)un;
	}
    }
    if (unptr != NULL)
	*unptr = un;
}`

