        vt->parser.intermed[vt->parser.intermedlen] = 0;
        do_csi(vt, c);
      }
      ENTER_NORMAL_STATE();
      break;
    case STRING:
      if(c == 0x07 || (c == 0x9c && !vt->mode.utf8)) {
        done_string(vt, string_start, bytes + pos - string_start);
        ENTER_NORMAL_STATE();
