    }
    else		    
    {
	if (ht == &vimvarht)
	{
	    EMSG2(_(e_illvar), name);
	    return;
	}
	if (!valid_varname(varname))
	    return;
	v = (dictitem_T *)alloc((unsigned)(sizeof(dictitem_T)
							  + STRLEN(varname)));
