	    else if (cnt > 99 && cur > 99)
		vim_snprintf(t, SEARCH_STAT_BUF_LEN, "[>99/>99]");
	    else if (cnt > 99)
		vim_snprintf(t, SEARCH_STAT_BUF_LEN, "[%d/>99]", cur);
