	clip_clear_selection(cb);
    row = check_row(row);
    col = check_col(col);
    col = mb_fix_col(col, row);
    cb->start.lnum  = row;
    cb->start.col   = col;
    cb->end	    = cb->start;
    cb->origin_row  = (short_u)cb->start.lnum;
    cb->state	    = SELECT_IN_PROGRESS;
#ifdef FEAT_TEXT_PROP
    if (wp != NULL && WIN_IS_POPUP(wp))
    {
	cb->min_col = wp->w_wincol + wp->w_popup_border[3];
