    {
	matchidx_T	currIdx = matches[i];
	if (i > 0)
	{
	    matchidx_T	prevIdx = matches[i - 1];
	    if (currIdx == (prevIdx + 1))
		score += SEQUENTIAL_BONUS;
	}
	if (currIdx > 0)
	{
	    int	neighbor;
	    int	curr;
	    int	neighborSeparator;
