{
    scriptitem_T    *si;
    int		    idx;
    imported_T	    *import;
    if (!SCRIPT_ID_VALID(current_sctx.sc_sid))
	return FAIL;
    si = SCRIPT_ITEM(current_sctx.sc_sid);
    idx = get_script_item_idx(current_sctx.sc_sid, name, 0, cctx);
    if (idx == -1 || si->sn_version != SCRIPT_VERSION_VIM9)
    {
	return generate_OLDSCRIPT(cctx, ISN_LOADS, name, current_sctx.sc_sid,
								       &t_any);
    }
    if (idx >= 0)
    {
	svar_T		*sv = ((svar_T *)si->sn_var_vals.ga_data) + idx;
	generate_VIM9SCRIPT(cctx, ISN_LOADSCRIPT,
					current_sctx.sc_sid, idx, sv->sv_type);
	return OK;
    }
    import = end == NULL ? NULL : find_imported(name, 0, FALSE, cctx);
    if (import != NULL)
    {
	char_u	*p = skipwhite(*end);
	char_u	*exp_name;
	int	cc;
	ufunc_T	*ufunc;
	type_T	*type;
	int	done = FALSE;
	int	res = OK;
	if (*p != '.')
	{
	    semsg(_(e_expected_dot_after_name_str), start);
	    return FAIL;
	}
	++p;
	if (VIM_ISWHITE(*p))
	{
	    emsg(_(e_no_white_space_allowed_after_dot));
	    return FAIL;
	}
	exp_name = p;
	while (eval_isnamec(*p))
	    ++p;
	cc = *p;
	*p = NUL;
	si = SCRIPT_ITEM(import->imp_sid);
	if (si->sn_autoload_prefix != NULL
					&& si->sn_state == SN_STATE_NOT_LOADED)
	{
	    char_u  *auto_name = concat_str(si->sn_autoload_prefix, exp_name);
	    if (cc == '(' || paren_follows_after_expr)
		res = generate_PUSHFUNC(cctx, auto_name, &t_func_any);
	    else
		res = generate_LOAD(cctx, ISN_LOADG, 0, auto_name, &t_any);
	    vim_free(auto_name);
	    done = TRUE;
	}
	else
	{
	    idx = find_exported(import->imp_sid, exp_name, &ufunc, &type,
								   cctx, TRUE);
	}
	*p = cc;
	p = skipwhite(p);
	*end = p;
	if (done)
	    return res;
	if (idx < 0)
	{
	    if (ufunc != NULL)
	    {
		generate_PUSHFUNC(cctx, ufunc->uf_name, NULL);
		return OK;
	    }
	    return FAIL;
	}
	generate_VIM9SCRIPT(cctx, ISN_LOADSCRIPT,
		import->imp_sid,
		idx,
		type);
	return OK;
    }
    if (error)
	semsg(_(e_item_not_found_str), name);
    return FAIL;
