{
    int		more;
    sock_T	fd;
    int		timeout;
    chanpart_T	*chanpart = &channel->ch_part[part];
    int		retval = FAIL;
    ch_log(channel, "Blocking read JSON for id %d", id);
    ++channel_blocking_wait;
    if (id >= 0)
	channel_add_block_id(chanpart, id);
    for (;;)
    {
	more = channel_parse_json(channel, part);
