	{
	    ch_log(channel, "Received JSON for id %d", id);
	    retval = OK;
	    break;
	}
	if (!more)
	{
	    if (channel_parse_messages())
		continue;
	    timeout = timeout_arg;
	    if (chanpart->ch_wait_len > 0)
	    {
