    case MBLOCK:
      block_prep(oap, &bd, lnum, FALSE);
      yank_copy_line(&bd, y_idx);
      break;
    case MLINE:
      y_current->y_array[y_idx] = vim_strsave(ml_get(lnum));
      break;
