      di = dictitem_alloc(lp->ll_newkey);
      if (dict_add(lp->ll_tv->vval.v_dict, di) == FAIL) {
        free(di);
        return;
      }
      lp->ll_tv = &di->di_tv;
    } else if (op != NULL && *op != '=') {
      tv_op(lp->ll_tv, rettv, op);
      return;
    } else
      clear_tv(lp->ll_tv);
    if (copy)
      copy_tv(rettv, lp->ll_tv);
    else {
      *lp->ll_tv = *rettv;
      lp->ll_tv->v_lock = 0;
      init_tv(rettv);
    }
  }
}`

