###Program before: `static size_t do_path_expand(garray_T *gap, const char_u *path,
                             size_t wildoff, int flags, bool didstar)
  FUNC_ATTR_NONNULL_ALL
{
  char_u      *buf;
  char_u      *p, *s, *e;
  int start_len = gap->ga_len;
  char_u      *pat;
  int starts_with_dot;
  int matches;
  int len;
  bool starstar = false;
  static int stardepth = 0;         
  if (stardepth > 0) {
    os_breakcheck();
    if (got_int)
      return 0;
  }
  buf = xmalloc(STRLEN(path) + BASENAMELEN + 5);
  p = buf;
  s = buf;
  e = NULL;
  const char_u *path_end = path;
  while (*path_end != NUL) {
    if (path_end >= path + wildoff && rem_backslash(path_end))
      *p++ = *path_end++;
    else if (*path_end == '/') {
      if (e != NULL)
        break;
      s = p + 1;
    } else if (path_end >= path + wildoff
               && (vim_strchr((char_u *)"*?[{~$", *path_end) != NULL
                   || (!p_fic && (flags & EW_ICASE)
                       && isalpha(PTR2CHAR(path_end)))))
      e = p;
    if (has_mbyte) {
      len = (*mb_ptr2len)(path_end);
      STRNCPY(p, path_end, len);
      p += len;
      path_end += len;
    } else
      *p++ = *path_end++;
  }
  e = p;
  *e = NUL;
  for (p = buf + wildoff; p < s; ++p)
    if (rem_backslash(p)) {
      STRMOVE(p, p + 1);
      --e;
      --s;
    }
  for (p = s; p < e; ++p)
    if (p[0] == '*' && p[1] == '*')
      starstar = true;
  starts_with_dot = (*s == '.');
  pat = file_pat_to_reg_pat(s, e, NULL, FALSE);
  if (pat == NULL) {
    xfree(buf);
    return 0;
  }
  regmatch_T regmatch;
#if defined(UNIX)
  regmatch.rm_ic = (flags & EW_ICASE) || p_fic;
#else
  regmatch.rm_ic = true;  
#endif
  if (flags & (EW_NOERROR | EW_NOTWILD))
    ++emsg_silent;
  regmatch.regprog = vim_regcomp(pat, RE_MAGIC);
  if (flags & (EW_NOERROR | EW_NOTWILD))
    --emsg_silent;
  xfree(pat);
  if (regmatch.regprog == NULL && (flags & EW_NOTWILD) == 0) {
    xfree(buf);
    return 0;
  }
  if (!didstar && stardepth < 100 && starstar && e - s == 2
      && *path_end == '/') {
    STRCPY(s, path_end + 1);
    ++stardepth;
    (void)do_path_expand(gap, buf, (int)(s - buf), flags, true);
    --stardepth;
  }
  *s = NUL;
  Directory dir;
  char *dirpath = (*buf == NUL ? "." : (char *)buf);
  if (os_file_is_readable(dirpath) && os_scandir(&dir, dirpath)) {
    char_u *name;
    scandir_next_with_dots(NULL );
    while((name = (char_u *) scandir_next_with_dots(&dir)) && name != NULL) {
      if ((name[0] != '.' || starts_with_dot)
          && ((regmatch.regprog != NULL && vim_regexec(&regmatch, name, 0))
              || ((flags & EW_NOTWILD)
                  && fnamencmp(path + (s - buf), name, e - s) == 0))) {
        STRCPY(s, name);
        len = STRLEN(buf);
        if (starstar && stardepth < 100) {
          STRCPY(buf + len, "/**");
          STRCPY(buf + len + 3, path_end);
          ++stardepth;
          (void)do_path_expand(gap, buf, len + 1, flags, true);
          --stardepth;
        }
        STRCPY(buf + len, path_end);
        if (path_has_exp_wildcard(path_end)) {      
          (void)do_path_expand(gap, buf, len + 1, flags, false);
        } else {
          if (*path_end != NUL)
            backslash_halve(buf + len + 1);
          if (os_file_exists(buf)) {          
            addfile(gap, buf, flags);
          }
        }
      }
    }
    os_closedir(&dir);
  }
  xfree(buf);
  vim_regfree(regmatch.regprog);
  matches = gap->ga_len - start_len;
  if (matches > 0)
    qsort(((char_u **)gap->ga_data) + start_len, matches,
        sizeof(char_u *), pstrcmp);
  return matches;
}`

