{
  char_u      *end;
  int         *p;
  int idx;
  char_u      *cpo_save;
  if (arg == NULL || arg[1] == NUL || arg[2] == NUL)
    return NULL;
  end = skip_regexp(arg + 1, *arg, TRUE, NULL);
  if (*end != *arg) {                       
    EMSG2(_("E401: Pattern delimiter not found: %s"), arg);
    return NULL;
  }
  ci->sp_pattern = vim_strnsave(arg + 1, (int)(end - arg - 1));
  cpo_save = p_cpo;
  p_cpo = (char_u *)"";
  ci->sp_prog = vim_regcomp(ci->sp_pattern, RE_MAGIC);
  p_cpo = cpo_save;
  if (ci->sp_prog == NULL)
    return NULL;
  ci->sp_ic = curwin->w_s->b_syn_ic;
  syn_clear_time(&ci->sp_time);
  ++end;
  do {
    for (idx = SPO_COUNT; --idx >= 0; )
      if (STRNCMP(end, spo_name_tab[idx], 3) == 0)
        break;
    if (idx >= 0) {
      p = &(ci->sp_offsets[idx]);
      if (idx != SPO_LC_OFF)
        switch (end[3]) {
        case 's':   break;
        case 'b':   break;
        case 'e':   idx += SPO_COUNT; break;
        default:    idx = -1; break;
        }
      if (idx >= 0) {
        ci->sp_off_flags |= (1 << idx);
        if (idx == SPO_LC_OFF) {            
          end += 3;
          *p = getdigits_int(&end);
          if (!(ci->sp_off_flags & (1 << SPO_MS_OFF))) {
            ci->sp_off_flags |= (1 << SPO_MS_OFF);
            ci->sp_offsets[SPO_MS_OFF] = *p;
          }
        } else {                          
          end += 4;
          if (*end == '+') {
            ++end;
            *p = getdigits_int(&end);                       
          } else if (*end == '-')   {
            ++end;
            *p = -getdigits_int(&end);                      
          }
        }
        if (*end != ',')
          break;
        ++end;
      }
    }
  } while (idx >= 0);
  if (!ends_excmd(*end) && !ascii_iswhite(*end)) {
    EMSG2(_("E402: Garbage after pattern: %s"), arg);
    return NULL;
  }
  return skipwhite(end);
}`

