###Program before: `static char_u *find_name_end(char_u *arg, char_u **expr_start,
                             char_u **expr_end, int flags)
{
  int mb_nest = 0;
  int br_nest = 0;
  char_u *p;
  int len;
  if (expr_start != NULL) {
    *expr_start = NULL;
    *expr_end = NULL;
  }
  if ((flags & FNE_CHECK_START) && !eval_isnamec1(*arg) && *arg != '{') {
    return arg;
  }
  for (p = arg; *p != NUL
       && (eval_isnamec(*p)
           || *p == '{'
           || ((flags & FNE_INCL_BR) && (*p == '[' || *p == '.'))
           || mb_nest != 0
           || br_nest != 0); mb_ptr_adv(p)) {
    if (*p == '\'') {
      for (p = p + 1; *p != NUL && *p != '\''; mb_ptr_adv(p))
        ;
      if (*p == NUL)
        break;
    } else if (*p == '"') {
      for (p = p + 1; *p != NUL && *p != '"'; mb_ptr_adv(p)) {
        if (*p == '\\' && p[1] != NUL) {
          ++p;
        }
      }
      if (*p == NUL) {
        break;
      }
    } else if (br_nest == 0 && mb_nest == 0 && *p == ':') {
      len = (int)(p - arg);
      if (len > 1
          || (len == 1 && vim_strchr(namespace_char, *arg) == NULL)) {
        break;
      }
    }
    if (mb_nest == 0) {
      if (*p == '[') {
        ++br_nest;
      } else if (*p == ']') {
        --br_nest;
      }
    }
    if (br_nest == 0) {
      if (*p == '{') {
        mb_nest++;
        if (expr_start != NULL && *expr_start == NULL) {
          *expr_start = p;
        }
      } else if (*p == '}') {
        mb_nest--;
        if (expr_start != NULL && mb_nest == 0 && *expr_end == NULL) {
          *expr_end = p;
        }
      }
    }
  }
  return p;
}`

