###Program before: `int os_nodetype(const char *name)
{
#ifdef WIN32
  if (STRNCMP(name, "\\\\.\\", 4) == 0) {
    return NODE_WRITABLE;
  }
#endif
  uv_stat_t statbuf;
  if (os_stat(name, &statbuf) == 0) {
    return NODE_NORMAL;
  }
#ifndef WIN32
  if (S_ISREG(statbuf.st_mode) || S_ISDIR(statbuf.st_mode)) {
    return NODE_NORMAL;
  }
  if (S_ISBLK(statbuf.st_mode)) {  
    return NODE_OTHER;
  }
#endif
  int nodetype = NODE_WRITABLE;
  int fd = os_open(name, O_RDONLY, 0);
  switch(uv_guess_handle(fd)) {
    case UV_TTY:         
      nodetype = NODE_WRITABLE;
      break;
    case UV_FILE:        
      nodetype = NODE_NORMAL;
      break;
    case UV_NAMED_PIPE:  
    case UV_UDP:         
    case UV_TCP:         
    case UV_UNKNOWN_HANDLE:
    default:
#ifdef WIN32
      nodetype = NODE_NORMAL;
#else
      nodetype = NODE_WRITABLE;  
#endif
      break;
  }
  close(fd);
  return nodetype;
}`

