      && wp->w_p_wrap
      && (wp->w_width != 0)) {
    numberextra = win_col_off(wp);
    col2 = col;
    colmax = (colnr_T)(wp->w_width - numberextra - col_adj);
    if (col >= colmax) {
        colmax += col_adj;
        n = colmax + win_col_off2(wp);
      if (n > 0) {
        colmax += (((col - colmax) / n) + 1) * n - col_adj;
      }
    }
