    if (!data->scroll_region_is_full_screen) {
      reset_scroll_region(ui);
    }
    cursor_goto(ui, saved_row, saved_col);
    if (!scroll_clears_to_current_colour) {
      clear_region(ui, clear_top, clear_bot, grid->left, grid->right);
