    if (fname[n - 1] == 'a') {          
      if (fname[n - 2] == 'a') {        
        EMSG(_("E326: Too many swap files found"));
        xfree(fname);
        fname = NULL;
        break;
      }
      --fname[n - 2];                   
      fname[n - 1] = 'z' + 1;
    }
    --fname[n - 1];                     
  }
  if (os_isdir((char_u *) dir_name)) {
    *found_existing_dir = true;
  } else if (!*found_existing_dir && **dirp == NUL) {
