      if (vim_fgets(linebuf, LBUFLEN, fd)) {
        break;      
      }
      line = linebuf;
    }
    if (diffstyle == DIFF_NONE) {
      if (isdigit(*line)) {
        diffstyle = DIFF_ED;
      } else if ((STRNCMP(line, "@@ ", 3) == 0)) {
        diffstyle = DIFF_UNIFIED;
      } else if ((STRNCMP(line, "--- ", 4) == 0)
