                 && (STRNCMP(line, "+++ ", 4) == 0)
                 && (vim_fgets(linebuf, LBUFLEN, fd) == 0)
                 && (STRNCMP(line, "@@ ", 3) == 0)) {
        diffstyle = DIFF_UNIFIED;
      }
