      if (parse_diff_ed(line, &lnum_orig, &count_orig,
                        &lnum_new, &count_new) == FAIL) {
        continue;
      }
    } else if (diffstyle == DIFF_UNIFIED) {
      if (STRNCMP(line, "@@ ", 3)  != 0) {
