###Program before: `void close_buffer(win_T *win, buf_T *buf, int action, int abort_if_last)
{
  bool unload_buf = (action != 0);
  bool del_buf = (action == DOBUF_DEL || action == DOBUF_WIPE);
  bool wipe_buf = (action == DOBUF_WIPE);
  bool is_curwin = (curwin != NULL && curwin->w_buffer == buf);
  win_T *the_curwin = curwin;
  tabpage_T *the_curtab = curtab;
  if (!buf->terminal) {
    if (buf->b_p_bh[0] == 'd') {         
      del_buf = true;
      unload_buf = true;
    } else if (buf->b_p_bh[0] == 'w') {  
      del_buf = true;
      unload_buf = true;
      wipe_buf = true;
    } else if (buf->b_p_bh[0] == 'u')    
      unload_buf = true;
  }
  if (buf->terminal && (unload_buf || del_buf || wipe_buf)) {
    unload_buf = true;
    del_buf = true;
    wipe_buf = true;
  }
  if (buf->b_locked > 0 && (del_buf || wipe_buf)) {
    EMSG(_("E937: Attempt to delete a buffer that is in use"));
    return;
  }
  if (win_valid_any_tab(win)) {
    if (buf->b_nwindows == 1) {
      set_last_cursor(win);
    }
    buflist_setfpos(buf, win,
        win->w_cursor.lnum == 1 ? 0 : win->w_cursor.lnum,
        win->w_cursor.col, TRUE);
  }
  bufref_T bufref;
  set_bufref(&bufref, buf);
  if (buf->b_nwindows == 1) {
    buf->b_locked++;
    if (apply_autocmds(EVENT_BUFWINLEAVE, buf->b_fname, buf->b_fname, false,
                       buf) && !bufref_valid(&bufref)) {
      EMSG(_(e_auabort));
      return;
    }
    buf->b_locked--;
    if (abort_if_last && one_window()) {
      EMSG(_(e_auabort));
      return;
    }
    if (!unload_buf) {
      buf->b_locked++;
      if (apply_autocmds(EVENT_BUFHIDDEN, buf->b_fname, buf->b_fname, false,
                         buf) && !bufref_valid(&bufref)) {
        EMSG(_(e_auabort));
        return;
      }
      buf->b_locked--;
      if (abort_if_last && one_window()) {
        EMSG(_(e_auabort));
        return;
      }
    }
    if (aborting())         
      return;
  }
