###Program before: `void scroll_to_fraction(win_T *wp, int prev_height)
{
    linenr_T lnum;
    int sline, line_size;
    int height = wp->w_height_inner;
  if (height > 0
      && (!wp->w_p_scb || wp == curwin)
      ) {
    lnum = wp->w_cursor.lnum;
    if (lnum < 1)               
      lnum = 1;
    wp->w_wrow = ((long)wp->w_fraction * (long)height - 1L) / FRACTION_MULT;
    line_size = plines_win_col(wp, lnum, (long)(wp->w_cursor.col)) - 1;
    sline = wp->w_wrow - line_size;
    if (sline >= 0) {
      const int rows = plines_win(wp, lnum, false);
      if (sline > wp->w_height_inner - rows) {
        sline = wp->w_height_inner - rows;
        wp->w_wrow -= rows - line_size;
      }
    }
    if (sline < 0) {
      wp->w_wrow = line_size;
      if (wp->w_wrow >= wp->w_height_inner
          && (wp->w_width_inner - win_col_off(wp)) > 0) {
        wp->w_skipcol += wp->w_width_inner - win_col_off(wp);
        wp->w_wrow--;
        while (wp->w_wrow >= wp->w_height_inner) {
          wp->w_skipcol += wp->w_width_inner - win_col_off(wp)
                           + win_col_off2(wp);
          wp->w_wrow--;
        }
      }
    } else if (sline > 0) {
      while (sline > 0 && lnum > 1) {
        (void)hasFoldingWin(wp, lnum, &lnum, NULL, true, NULL);
        if (lnum == 1) {
          line_size = 1;
          --sline;
          break;
        }
        lnum--;
        if (lnum == wp->w_topline) {
          line_size = plines_win_nofill(wp, lnum, true)
                      + wp->w_topfill;
        } else {
          line_size = plines_win(wp, lnum, true);
        }
        sline -= line_size;
      }
      if (sline < 0) {
        (void)hasFoldingWin(wp, lnum, NULL, &lnum, true, NULL);
        lnum++;
        wp->w_wrow -= line_size + sline;
      } else if (sline > 0) {
        lnum = 1;
        wp->w_wrow -= sline;
      }
    }
    set_topline(wp, lnum);
  }
  if (wp == curwin) {
    if (p_so)
      update_topline();
    curs_columns(FALSE);        
  }
  if (prev_height > 0) {
    wp->w_prev_fraction_row = wp->w_wrow;
  }
  win_comp_scroll(wp);
  redraw_win_later(wp, SOME_VALID);
  wp->w_redr_status = TRUE;
  invalidate_botline_win(wp);
}`

