      return;
    }
  }
  if (*eap->arg != NUL) {
    set_string_option_direct((char_u *)"ef", -1, eap->arg, OPT_FREE, 0);
  }
  char_u *enc = (*curbuf->b_p_menc != NUL) ? curbuf->b_p_menc : p_menc;
