    EMSG2(_("E760: No word count in %s"), fname);
  while (!vim_fgets(line, MAXLINELEN, fd) && !got_int) {
    line_breakcheck();
    ++lnum;
    if (line[0] == '#' || line[0] == '/')
      continue;         
    l = (int)STRLEN(line);
    while (l > 0 && line[l - 1] <= ' ')
      --l;
    if (l == 0)
      continue;         
    line[l] = NUL;
