      pc = string_convert(&spin->si_conv, line, NULL);
      if (pc == NULL) {
        smsg(_("Conversion failure for word in %s line %d: %s"),
             fname, lnum, line);
        continue;
      }
      w = pc;
    } else {
      pc = NULL;
      w = line;
    }
    afflist = NULL;
    for (p = w; *p != NUL; MB_PTR_ADV(p)) {
      if (*p == '\\' && (p[1] == '\\' || p[1] == '/')) {
        STRMOVE(p, p + 1);
      } else if (*p == '/') {
        *p = NUL;
        afflist = p + 1;
        break;
      }
    }
    if (spin->si_ascii && has_non_ascii(w)) {
      ++non_ascii;
      xfree(pc);
      continue;
