              CONDIT_SUF, flags, store_afflist, pfxlen) == FAIL)
        retval = FAIL;
    }
    xfree(pc);
  }
  if (duplicate > 0)
    smsg(_("%d duplicate word(s) in %s"), duplicate, fname);
  if (spin->si_ascii && non_ascii > 0)
