      if (++msg_row >= Rows)        
        msg_row = Rows - 1;
    } else if (*s == '\r') {      
      msg_col = 0;
    } else if (*s == '\b') {      
      if (msg_col)
        --msg_col;
    } else if (*s == TAB) {       
      do {
        msg_screen_putchar(' ', attr);
      } while (msg_col & 7);
    } else if (*s == BELL) {  
      vim_beep(BO_SH);
    } else if (*s >= 0x20) {  
      cw = utf_ptr2cells(s);
      if (maxlen >= 0) {
        l = utfc_ptr2len_len(s, (int)((str + maxlen) - s));
      } else {
        l = utfc_ptr2len(s);
      }
      if (cmdmsg_rl || (cw > 1 && msg_col + t_col >= Columns - 1)) {
        if (l > 1) {
          s = screen_puts_mbyte((char_u *)s, l, attr) - 1;
        } else {
          msg_screen_putchar(*s, attr);
        }
      } else {
        if (t_col == 0)
          t_s = s;
        t_col += cw;
        s += l - 1;
      }
    }
    ++s;
  }
  if (t_col > 0) {
    t_puts(&t_col, t_s, s, attr);
  }
  if (p_more && !recurse) {
    store_sb_text((char_u **)&sb_str, (char_u *)s, attr, &sb_col, false);
  }
  msg_check();
}`

