      else node->tok = mpack_pack_str(lmpack_objlen(L, NULL));
      break;
    }
    case LUA_TTABLE: {
      int is_array;
      mpack_uint32_t len;
      mpack_node_t *n;
      if (packer->ext != LUA_NOREF && lua_getmetatable(L, -1)) {
        lmpack_geti(L, packer->reg, packer->ext);
        lua_pushvalue(L, -2);
        lua_gettable(L, -2);
        if (lua_isfunction(L, -1)) {
