        if (paren != NULL) {
            const ptrdiff_t delim_len = paren - delim;
            for (p += 3; *p; ++p)
                if (p[0] == ')' && STRNCMP(p + 1, delim, delim_len) == 0
                        && p[delim_len + 1] == '"')
                {
                    p += delim_len + 1;
                    break;
                }
            if (p[0] == '"') {
              continue;  
            }
        }
    }
    break;                                  
  }
  if (!*p) {
    p--;                                    
  }
  return p;
}`

